  String audio = settings.audioOutput == AudioOutput::RCA        ? PTBR::RCA
                 : settings.audioOutput == AudioOutput::INTERNAL ? PTBR::ALTO_FALANTE_INTERNO
                                                                 : PTBR::MUDO;
